<div class="page-head"><div><p class="eyebrow">CATÁLOGO DEL CORE</p><h1>Productos</h1><p class="muted">Define el nivel de seguridad y la prioridad que usará el optimizador.</p></div><a class="boton boton--primario" href="<?= site_url('productos/nuevo') ?>">Nuevo producto <span>＋</span></a></div>
<section class="card"><div class="card__head"><div><h2>Catálogo activo</h2><p class="muted small">El código se valida en back-end y no se permite duplicarlo.</p></div><span class="counter"><?= count($productos) ?> registros</span></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Producto</th><th>Unidad</th><th>Stock seguridad</th><th>Saldo</th><th>Prioridad</th><th></th></tr></thead><tbody><?php if ($productos === []): ?><tr><td colspan="7" class="empty">No hay productos registrados.</td></tr><?php endif; ?><?php foreach ($productos as $producto): ?><tr class="<?= ! $producto['activo'] ? 'row-muted' : '' ?>"><td><code><?= esc($producto['codigo']) ?></code></td><td><strong><?= esc($producto['nombre']) ?></strong><?= ! $producto['activo'] ? '<small>Inactivo</small>' : '' ?></td><td><?= esc($producto['unidad']) ?></td><td><?= (int) $producto['stock_seguridad'] ?></td><td><strong><?= (int) ($saldos[$producto['id']] ?? 0) ?></strong></td><td><span class="priority priority--<?= (int) $producto['prioridad'] ?>"><?= (int) $producto['prioridad'] === 3 ? 'Alta' : ((int) $producto['prioridad'] === 2 ? 'Media' : 'Baja') ?></span></td><td><a class="text-link" href="<?= site_url('productos/' . $producto['id'] . '/editar') ?>">Editar</a><?php if ($producto['activo']): ?><form class="inline-form" method="post" action="<?= site_url('productos/' . $producto['id'] . '/eliminar') ?>"><?= csrf_field() ?><button class="link-button danger" type="submit">Desactivar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
